{
  "schema": "plan-v1",
  "steps": [
    {
      "id": "survey-src",
      "action": "Read all files under src/** to inventory modules, existing JSDoc type annotations, and the public entry point's exported symbols, noting patterns likely to violate full TypeScript strictness (implicit any, missing null/undefined narrowing, unsafe casts).",
      "tools": ["read", "grep"],
      "rounds": 15,
      "exit": [
        {"type": "json-valid", "path": "tsconfig.json"}
      ]
    },
    {
      "id": "catalog-suppressions-and-any",
      "action": "Grep across src/** for existing @ts-ignore, @ts-expect-error, @ts-nocheck comments and any JSDoc using `any` or `{*}`, and list every symbol exported from the package's public entry point so none can be lost later.",
      "tools": ["grep", "read"],
      "rounds": 10,
      "exit": [
        {"type": "json-valid", "path": "package.json"}
      ]
    },
    {
      "id": "annotate-strict-types",
      "action": "Edit JSDoc type annotations and add necessary null/undefined narrowing throughout src/** so the code satisfies full TypeScript strictness (strictNullChecks, noImplicitAny, strictFunctionTypes, etc.) without changing runtime behavior, without using `any` or `{*}` in JSDoc, and without adding any new @ts-ignore, @ts-expect-error, or @ts-nocheck suppressions.",
      "tools": ["read", "edit"],
      "rounds": 35,
      "target": "src/**",
      "exit": [
        {"type": "tree-changed", "scope": "src/**"},
        {"type": "check-passes", "name": "typecheck-clean"}
      ]
    },
    {
      "id": "fix-remaining-errors-preserve-exports",
      "action": "Resolve any remaining strict-mode typecheck errors across src/**, ensuring every symbol previously exported from the package's public entry point is still exported and no suppression comments or `any`/`{*}` JSDoc types were introduced.",
      "tools": ["read", "edit"],
      "rounds": 30,
      "target": "src/**",
      "exit": [
        {"type": "tree-changed", "scope": "src/**"},
        {"type": "check-passes", "name": "no-suppressions"}
      ]
    },
    {
      "id": "final-verification",
      "action": "Confirm the full strict typecheck passes cleanly, the published .d.ts still builds, and the existing test suite remains green with no tests lost.",
      "tools": ["read"],
      "rounds": 10,
      "exit": [
        {"type": "check-passes", "name": "suite-green"}
      ]
    }
  ]
}

{
  "schema": "plan-v1",
  "steps": [
    {
      "id": "survey-source",
      "action": "Read every file under src/** plus the package entry point and its package.json 'exports'/'main' field to catalog: (a) every currently exported public symbol, (b) all existing JSDoc type annotations, (c) any existing @ts-ignore/@ts-expect-error/@ts-nocheck comments, (d) any JSDoc types using 'any' or the '{*}' wildcard. Note which files will need annotation fixes to satisfy `tsc --noEmit --strict` (strictNullChecks, noImplicitAny, strictFunctionTypes, etc.) while preserving runtime behavior exactly.",
      "tools": ["read", "grep"],
      "rounds": 20,
      "exit": [
        {"type": "json-valid", "path": "package.json"}
      ]
    },
    {
      "id": "fix-primary-modules",
      "action": "Edit the main/core JavaScript source files under src/** to add or correct JSDoc type annotations so they satisfy `tsc --noEmit --strict`. Use precise JSDoc types (@param, @returns, @typedef, generics, union types) and use 'unknown' plus narrowing at use sites where the true type is not statically knowable. Do not introduce any @ts-ignore, @ts-expect-error, or @ts-nocheck, and do not introduce any JSDoc type containing 'any' or '{*}'. Do not change any runtime logic, control flow, or exported symbol names/signatures — only add/correct type annotations that describe existing behavior.",
      "tools": ["read", "grep", "edit"],
      "rounds": 40,
      "target": "src/**",
      "exit": [
        {"type": "tree-changed", "scope": "src/**"},
        {"type": "check-passes", "name": "typecheck-clean"}
      ]
    },
    {
      "id": "fix-remaining-modules",
      "action": "Continue fixing any remaining files under src/** that still produce errors under `tsc --noEmit --strict` (e.g. helper/utility modules, internal submodules not covered in the previous pass). Same constraints apply: only JSDoc annotation fixes, no suppressions, no 'any' or '{*}' types, 'unknown' allowed with narrowing, no behavior changes, no removed exports.",
      "tools": ["read", "grep", "edit"],
      "rounds": 40,
      "target": "src/**",
      "exit": [
        {"type": "tree-changed", "scope": "src/**"},
        {"type": "check-passes", "name": "typecheck-clean"}
      ]
    },
    {
      "id": "final-strictness-pass",
      "action": "Perform a final cleanup pass over src/**: resolve any lingering strict-mode typecheck errors (e.g. from edge cases like optional chaining, nullable properties, or generic inference gaps), double-check no @ts-ignore/@ts-expect-error/@ts-nocheck or 'any'/'{*}' JSDoc types were introduced anywhere, and confirm every previously exported public symbol from the entry point is still exported unchanged. Only touch src/** and only via type annotations, never behavior.",
      "tools": ["read", "grep", "edit"],
      "rounds": 30,
      "target": "src/**",
      "exit": [
        {"type": "tree-changed", "scope": "src/**"},
        {"type": "check-passes", "name": "typecheck-clean"}
      ]
    },
    {
      "id": "verify-behavior-and-suite",
      "action": "Read through the modified src/** files and confirm the test suite's behavior oracle still holds and no suppressions or 'any'/'{*}' types were left in place; rely on the automatic checks to confirm the suite is green and no suppressions were added.",
      "tools": ["read", "grep"],
      "rounds": 15,
      "exit": [
        {"type": "check-passes", "name": "suite-green"},
        {"type": "check-passes", "name": "no-suppressions"}
      ]
    }
  ]
}

